// Service worker registration and the update prompt. The worker itself is generated by
// vite-plugin-pwa (see vite.config.js) and precaches the whole app for offline play.
import { registerSW } from "virtual:pwa-register";
import * as icon from "./icons.js";

const CHECK_EVERY_MS = 60 * 60 * 1000;   // installed apps can stay open for days

const toastEl = document.getElementById("toast");
let hideTimer = null;

function showToast(html, { autoHideMs } = {}) {
  clearTimeout(hideTimer);
  toastEl.innerHTML = `<div class="toast">${html}</div>`;
  if (autoHideMs) hideTimer = setTimeout(hideToast, autoHideMs);
}

function hideToast() {
  clearTimeout(hideTimer);
  toastEl.innerHTML = "";
}

// `beforeReload` lets the app save in-progress state before the new version takes over.
export function setupServiceWorker({ beforeReload }) {
  const updateSW = registerSW({
    onNeedRefresh() {
      showToast(`
        <span class="toast-text">A new version is available.</span>
        <button class="btn btn-primary" data-pwa="reload">Reload</button>
        <button class="icon-btn toast-close" data-pwa="dismiss" aria-label="Dismiss">${icon.close}</button>`);
    },
    onOfflineReady() {
      showToast(`<span class="toast-text">Ready to play offline.</span>`, { autoHideMs: 4000 });
    },
    onRegisteredSW(_url, registration) {
      if (!registration) return;
      // Look for a new version whenever the app comes back into view, and hourly while open.
      document.addEventListener("visibilitychange", () => {
        if (!document.hidden) registration.update();
      });
      setInterval(() => registration.update(), CHECK_EVERY_MS);
    },
    onRegisterError(err) {
      console.error("Service worker registration failed", err);
    },
  });

  toastEl.addEventListener("click", async event => {
    const action = event.target.closest("[data-pwa]")?.dataset.pwa;
    if (action === "dismiss") hideToast();
    if (action === "reload") {
      await beforeReload();
      updateSW(true);   // activates the waiting worker, then reloads the page
    }
  });
}
